let platformsGenerated = false;
let crystals = [];
let nextZ = -100;
function start() {
  if (platformsGenerated) return;
  platformsGenerated = true;
  const seed = Math.random() * 10000;
  const noise = (x, z) => {
    const n = Math.sin(x * 12.7 + z * 31.1 + seed) * 43758.5453;
    return n - Math.floor(n);
  };
  // Generate initial chunk (20 platforms)
  for (let i = 1; i <= 20; i++) {
    generatePlatform(i, seed, noise);
  }
  nextZ = -20 * 4 - 6;
}
function generatePlatform(i, seed, noise) {
  const z = -i * 4 - 2;
  const x = (noise(i, 0) - 0.5) * 6;
  const y = i * 0.4 + (noise(i, 1) - 0.5) * 0.5;
  const width = 2 + noise(i, 2) * 2;
  const depth = 2 + noise(i, 3) * 2;
  const id = 'platform-' + i;
  engine.spawn(id, {
    kind: 'box',
    x: x,
    y: y,
    z: z,
    scale: [width, 0.9, depth],
    color: '#c7c6b2',
    physics: 'static',
    behavior: 'none',
    visible: true
  });
  if (noise(i, 4) < 0.2) {
    const crystalId = 'crystal-' + i;
    crystals.push(crystalId);
    engine.spawn(crystalId, {
      kind: 'sphere',
      x: x,
      y: y + 1.5,
      z: z,
      scale: [0.48, 0.72, 0.48],
      color: '#89eacf',
      physics: 'none',
      behavior: 'collectible'
    });
  }
  if (i % 5 === 0) {
    const cpId = 'checkpoint-' + i;
    engine.spawn(cpId, {
      kind: 'cylinder',
      x: x,
      y: y + 0.5,
      z: z + 2,
      scale: [2.7, 0.06, 2.7],
      color: '#77dabc',
      physics: 'none',
      behavior: 'checkpoint'
    });
  }
}
function update(dt, time, input) {
  const p = engine.get('player');
  if (p) {
    // Infinite generation: spawn ahead when player approaches end
    if (p.z > nextZ + 30 || (nextZ > p.z + 30 && platformsGenerated)) {
      // Generate new chunk of 5 platforms ahead
      const chunkStart = Math.floor(p.z / 20) * 20 + 20;
      const seed = Math.random() * 10000;
      const noise = (x, z) => {
        const n = Math.sin(x * 12.7 + z * 31.1 + seed) * 43758.5453;
        return n - Math.floor(n);
      };
      for (let i = 1; i <= 5; i++) {
        const idx = Math.floor(p.z / 20) + i + 20;
        const id = 'platform-' + idx + '-' + Math.round(Math.random()*1000);
        const z = -idx * 4 - 2;
        const x = (noise(idx, 0) - 0.5) * 6;
        const y = idx * 0.4 + (noise(idx, 1) - 0.5) * 0.5;
        const width = 2 + noise(idx, 2) * 2;
        const depth = 2 + noise(idx, 3) * 2;
        engine.spawn(id, {
          kind: 'box',
          x: x,
          y: y,
          z: z,
          scale: [width, 0.9, depth],
          color: '#c7c6b2',
          physics: 'static',
          behavior: 'none',
          visible: true
        });
        if (noise(idx, 4) < 0.2) {
          const crystalId = 'crystal-' + idx + '-' + Math.round(Math.random()*1000);
          crystals.push(crystalId);
          engine.spawn(crystalId, {
            kind: 'sphere',
            x: x,
            y: y + 1.5,
            z: z,
            scale: [0.48, 0.72, 0.48],
            color: '#89eacf',
            physics: 'none',
            behavior: 'collectible'
          });
        }
        if (idx % 5 === 0) {
          const cpId = 'checkpoint-' + idx + '-' + Math.round(Math.random()*1000);
          engine.spawn(cpId, {
            kind: 'cylinder',
            x: x,
            y: y + 0.5,
            z: z + 2,
            scale: [2.7, 0.06, 2.7],
            color: '#77dabc',
            physics: 'none',
            behavior: 'checkpoint'
          });
        }
        nextZ = Math.min(nextZ, z);
      }
    }
    // Update HUD
    const collected = crystals.filter(id => {
      const obj = engine.get(id);
      return obj && !obj.visible;
    }).length;
    const dist = Math.round(Math.abs(p.z));
    engine.ui('hud.score', { text: 'CRISTAIS: ' + collected + ' / 20+' });
    engine.ui('hud.level', { text: 'DIST: ' + dist + ' m' });
  }
}
